package com.visionerp.controller; import com.visionerp.entity.*; import com.visionerp.repository.*; import com.visionerp.service.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/attendance") public class AttendanceController {private final AttendanceRepository a;private final EmployeeRepository e;private final NotificationService n;private final AuditService audit;public AttendanceController(AttendanceRepository a,EmployeeRepository e,NotificationService n,AuditService audit){this.a=a;this.e=e;this.n=n;this.audit=audit;}@GetMapping("/today")public List<Attendance> today(){return a.findByWorkDateOrderByCheckInDesc(LocalDate.now());}@GetMapping("/employee/{id}")public List<Attendance> employee(@PathVariable Long id){return a.findByEmployeeIdOrderByWorkDateDesc(id);}@PostMapping("/check-in/{employeeId}")@PreAuthorize("hasAnyRole('ADMIN','HR','SECURITY','EMPLOYEE')")public Attendance checkIn(@PathVariable Long employeeId,org.springframework.security.core.Authentication auth){Employee emp=e.findById(employeeId).orElseThrow();LocalDate d=LocalDate.now();Attendance x=a.findByEmployeeIdAndWorkDate(employeeId,d).orElseGet(()->{Attendance z=new Attendance();z.employee=emp;z.workDate=d;return z;});if(x.checkIn!=null)return x;x.checkIn=LocalDateTime.now();x.status=x.checkIn.toLocalTime().isAfter(LocalTime.of(9,15))?"LATE":"PRESENT";x.source="MANUAL";Attendance saved=a.save(x);n.send(emp.email,"ATTENDANCE","Attendance recorded: "+x.status);audit.log(auth.getName(),"CHECK_IN","ATTENDANCE",saved.id.toString(),emp.employeeCode);return saved;}@PostMapping("/check-out/{employeeId}")public Attendance checkOut(@PathVariable Long employeeId,org.springframework.security.core.Authentication auth){Attendance x=a.findByEmployeeIdAndWorkDate(employeeId,LocalDate.now()).orElseThrow();x.checkOut=LocalDateTime.now();if(x.checkIn!=null)x.workMinutes=Duration.between(x.checkIn,x.checkOut).toMinutes();Attendance saved=a.save(x);audit.log(auth.getName(),"CHECK_OUT","ATTENDANCE",saved.id.toString(),"minutes="+x.workMinutes);return saved;}}
